        const plan=item.payload;const {canonicalDigest,...withoutDigest}=plan;if(plan.ownerId!==batch.ownerId||canonicalDigest!==item.canonicalDigest||canonicalDigest!==sha256Digest(contentPlanCanonicalPayload(withoutDigest)))throw new PersistentRuntimeError('SUBMISSION_INPUT_MISMATCH','MATERIALIZED_PLAN_INVALID');
