        const head=(await client.query<{current_revision:number;current_digest:string;row_version:number}>('select current_revision,current_digest,row_version from content_plan_heads_v2 where owner_profile_id=$1 and plan_id=$2 for update',[batch.ownerId,plan.planId])).rows[0];if(head===undefined){if(item.expectedHeadDigest!==null||plan.revision!==1||plan.parentDigest!==null)throw new PersistentRuntimeError('SUBMISSION_INPUT_MISMATCH','PLAN_VERSION_CONFLICT');}else if(head.current_digest.trim()!==item.expectedHeadDigest||plan.parentDigest!==item.expectedHeadDigest||plan.revision!==head.current_revision+1)throw new PersistentRuntimeError('SUBMISSION_INPUT_MISMATCH','PLAN_VERSION_CONFLICT');
